input.new_string:
while [[ $# -gt 0 ]]; do
    case "$1" in
        --stream)              shift 2 ;;
        --done-sentinel)       shift 2 ;;
        --status-file)         shift 2 ;;
        --quiet-log)           shift 2 ;;
        --surfaced-sentinel)   shift 2 ;;
        --paired-pid-file)     shift 2 ;;
        --poll-interval=*|--rate-cap=*|--final-tail-lines=*|--mode=*)
            shift ;;
        -h|--help)
            usage
            exit 0
            ;;
        *)
            shift ;;
    esac
done
